import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { TranslatePipe } from '../../pipes/translate.pipe';

@Component({
  selector: 'app-hero',
  standalone: true,
  imports: [CommonModule, TranslatePipe],
  template: `
    <section class="hero-section">
      <div class="container hero-content">
        <div class="hero-text fade-in">
          <span class="greeting">{{ 'hero.greeting' | translate }}</span>
          <h1>Zakariae OUKHAMOU</h1>
          <h2 class="role">{{ 'hero.role' | translate }}</h2>
          <p class="description">
            Building performant, secure, and beautiful web experiences.
            Specialized in Angular & Spring Boot.
          </p>
          <div class="cta-buttons">
            <a href="#projects" class="btn btn-primary">{{ 'hero.btn.projects' | translate }}</a>
            <a href="#contact" class="btn btn-outline">{{ 'hero.btn.contact' | translate }}</a>
          </div>
        </div>
        <div class="hero-decoration">
          <!-- Abstract Circle or Image -->
          <div class="circle"></div>
        </div>
      </div>
    </section>
  `,
  styles: [`
    .hero-section {
      height: 100vh;
      display: flex;
      align-items: center;
      position: relative;
      overflow: hidden;
      padding-top: 80px; /* Offset for navbar */
    }

    .hero-content {
      display: flex;
      justify-content: space-between;
      align-items: center;
      width: 100%;
    }

    .hero-text {
      max-width: 600px;
      z-index: 2;

      .greeting {
        color: var(--primary-color);
        font-weight: 600;
        font-size: 1.2rem;
        display: block;
        margin-bottom: 0.5rem;
      }

      h1 {
        font-size: 3.5rem;
        margin-bottom: 0.5rem;
        background: linear-gradient(to right, var(--text-color), var(--primary-color));
        -webkit-background-clip: text;
        -webkit-text-fill-color: transparent;
      }

      .role {
        font-size: 1.8rem;
        color: var(--secondary-color);
        margin-bottom: 1.5rem;
      }

      .description {
        font-size: 1.1rem;
        color: var(--text-color);
        opacity: 0.8;
        margin-bottom: 2.5rem;
        line-height: 1.6;
      }
    }

    .cta-buttons {
      display: flex;
      gap: 1rem;
    }

    .hero-decoration {
      position: absolute;
      right: -10%;
      top: 50%;
      transform: translateY(-50%);
      z-index: 1;
      opacity: 0.1;

      .circle {
        width: 500px;
        height: 500px;
        border-radius: 50%;
        background: linear-gradient(45deg, var(--primary-color), var(--secondary-color));
        filter: blur(80px);
      }
    }

    @media (max-width: 768px) {
      .hero-text {
        text-align: center;
        margin: 0 auto;

        h1 { font-size: 2.5rem; }
        .cta-buttons { justify-content: center; }
      }
      .hero-decoration { display: none; }
    }
  `]
})
export class HeroComponent { }
